// TestResolveVariablesServerScope is tmdb-enrichment D4's substitution seam:
// a redacted_ref scoped "server:<name>" resolves from the resolved-secrets map
// (mixed freely beside ordinary string variables); a server ref whose name is
// absent from the map stays the explicit errRedactedRef — spec class, never
// relayed.
func TestResolveVariablesServerScope(t *testing.T) {
	vars := map[string]*metadatav1.VariableValue{
		"query":   stringVar("blade runner"),
		"api_key": redactedRefVar("server:api_key"),
	}

	got, err := resolveVariables(vars, map[string]string{"api_key": "sekrit"})
	if err != nil {
		t.Fatalf("resolveVariables: %v", err)
	}
	if got["api_key"] != "sekrit" || got["query"] != "blade runner" {
		t.Fatalf("resolved = %v, want the secret and the string side by side", got)
	}

	// The same ref with an unresolved name stays the explicit unsupported
	// error (errors.Is — the spec-class classifier and the relay skip both
	// read it through the chain).
	if _, err := resolveVariables(vars, map[string]string{}); !errors.Is(err, errRedactedRef) {
		t.Fatalf("err = %v, want errRedactedRef for the unresolved server name", err)
	}
	if _, err := resolveVariables(vars, nil); !errors.Is(err, errRedactedRef) {
		t.Fatalf("err = %v, want errRedactedRef with no secrets map (pre-SERVER behavior)", err)
	}
}

