// unbuilt.
func TestResolveVariablesClientScopeUnsupported(t *testing.T) {
	vars := map[string]*metadatav1.VariableValue{"token": redactedRefVar("client:token")}

	// Populated map proves the refusal is unconditional, not a lookup miss.
	if _, err := resolveVariables(vars, map[string]string{"token": "t"}); !errors.Is(err, errRedactedRef) {
		t.Fatalf("err = %v, want errRedactedRef for a client: ref even with a same-named secret", err)
	}

	if _, err := resolveVariables(map[string]*metadatav1.VariableValue{"k": redactedRefVar("worker:k")}, map[string]string{"k": "v"}); !errors.Is(err, errRedactedRef) {
		t.Fatalf("err = %v, want errRedactedRef for an unrecognized scope", err)
	}
}

// TestRunSourcePassesServerAuthContext is D4 + flag 3 at the chain: a SERVER
// binding whose declared secrets all resolve against its Options JSON sends
// BuildRequest the MODE-ONLY SERVER AuthContext (values never enter the
// plugin) and the fetch serves the resolved key; an unresolvable name keeps
// the empty AuthContext and today's spec-class failure; the nil closure is
// vacuous-SERVER for a names-nothing plugin and byte-identical empty for a
// non-SERVER binding.
func TestRunSourcePassesServerAuthContext(t *testing.T) {
	t.Run("resolved SERVER binding: mode-only auth, secret serves the fetch", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		src := &authSource{planSource: planSource{
			primary: &metadatav1.RequestSpec{
				Method: "GET", UrlTemplate: srv.URL + "/3/search/movie?query={query}&api_key={api_key}",
				Variables: map[string]*metadatav1.VariableValue{
					"query":   stringVar("blade"),
					"api_key": redactedRefVar("server:api_key"),
				},
			},
		}}
		b := serverBinding(`{"api_key":"sekrit"}`)
		sr := runAuthSource(src, b, func(string) []string { return []string{"api_key"} })

		if sr.kind != outcomeSucceeded {
			t.Fatalf("kind = %v (err %q), want succeeded", sr.kind, sr.errMsg)
		}
		if src.gotAuth.GetMode() != commonv1.AuthContext_SERVER {
			t.Fatalf("auth mode = %v, want SERVER", src.gotAuth.GetMode())
		}
		if src.gotAuth.GetServerSecrets() != nil {
			t.Fatal("AuthContext carries ServerSecrets; the values NEVER ride to the plugin (flag 3)")
		}
		if q := rec.query(0); q != "query=blade&api_key=sekrit" {
			t.Fatalf("upstream query = %q, want the resolved secret substituted core-side", q)
		}
	})

	t.Run("unresolvable declared name: empty AuthContext as today, spec-class failure", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		src := &authSource{planSource: planSource{
			primary: &metadatav1.RequestSpec{
				Method: "GET", UrlTemplate: srv.URL + "/3/search/movie?query={api_key}",
				Variables: map[string]*metadatav1.VariableValue{"api_key": redactedRefVar("server:api_key")},
			},
		}}
		b := serverBinding(`{}`) // the secret the handshake declares is missing
		sr := runAuthSource(src, b, func(string) []string { return []string{"api_key"} })

		if src.gotAuth.GetMode() != commonv1.AuthContext_AUTH_MODE_UNSPECIFIED || src.gotAuth.GetServerSecrets() != nil {
			t.Fatalf("auth = %v/%v, want the empty AuthContext (chain.go's today shape)", src.gotAuth.GetMode(), src.gotAuth.GetServerSecrets())
		}
		if sr.kind != outcomeFailed || sr.fetchClass != fetchClassSpec {
			t.Fatalf("outcome = %v/%q, want a spec-class fetch failure", sr.kind, sr.fetchClass)
		}
		if rec.count() != 0 {
			t.Fatal("the upstream saw a request; an unresolved secret must abort before any network attempt")
		}
	})

	t.Run("nil closure: vacuous SERVER auth; non-SERVER binding stays empty", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()

		// A SERVER binding over a plugin that declares no secrets: vacuously
		// resolved — mode-only SERVER auth, nothing to substitute.
		plain := &authSource{planSource: planSource{
			primary: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL + "?which=plain"},
		}}
		sr := runAuthSource(plain, serverBinding(""), nil)
		if sr.kind != outcomeSucceeded || plain.gotAuth.GetMode() != commonv1.AuthContext_SERVER {
			t.Fatalf("outcome = %v, auth mode = %v, want succeeded + SERVER (vacuously resolved)", sr.kind, plain.gotAuth.GetMode())
		}

		// A non-SERVER binding (today's shikimori shape): the empty
		// AuthContext byte-identically, no matter the closure.
		legacy := &authSource{planSource: planSource{
			primary: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL + "?which=legacy"},
		}}
		sr = runAuthSource(legacy, binding("plan", 1, true), func(string) []string { return []string{"api_key"} })
		if sr.kind != outcomeSucceeded || legacy.gotAuth.GetMode() != commonv1.AuthContext_AUTH_MODE_UNSPECIFIED {
			t.Fatalf("outcome = %v, auth mode = %v, want succeeded + empty AuthContext (byte-identical legacy)", sr.kind, legacy.gotAuth.GetMode())
		}
	})
}

// TestBuildPlanResolvesServerSecrets is D4's relay leg: the plan resolves
// server refs through the same seam, so a handed-off descriptor is
// server-authored (client-relayed-fetch's rule — no placeholder, no
// {server:...} ref ever reaches a relay principal); without the secrets the
// nil plan keeps today's relay skip (the normal fetch fails spec-class).
func TestBuildPlanResolvesServerSecrets(t *testing.T) {
	primary := &metadatav1.RequestSpec{
		Method: "GET", UrlTemplate: "https://upstream/3/movie/{tmdb_id}?api_key={api_key}",
		Variables: map[string]*metadatav1.VariableValue{
			"tmdb_id": stringVar("550"),
			"api_key": redactedRefVar("server:api_key"),
		},
	}
	extra := &metadatav1.RequestSpec{
		Method: "GET", UrlTemplate: "https://upstream/3/movie/550/credits?api_key={api_key}",
		Variables: map[string]*metadatav1.VariableValue{"api_key": redactedRefVar("server:api_key")},
	}

	plan := buildPlan(primary, []*metadatav1.RequestSpec{extra}, map[string]string{"api_key": "sekrit"})
	if len(plan) != 2 {
		t.Fatalf("plan len = %d, want 2 (primary + extra, positional)", len(plan))
	}
	want := []string{
		"https://upstream/3/movie/550?api_key=sekrit",
		"https://upstream/3/movie/550/credits?api_key=sekrit",
	}
	for i, url := range want {
		if plan[i].URL != url {
			t.Fatalf("plan[%d].url = %q, want fully substituted %q", i, plan[i].URL, url)
		}
	}

	// No secrets (variadic absent, nil, or missing the name): the unresolved
	// ref yields nil — the relay path skips, today's behavior.
	for _, got := range [][]relay.PlanSpec{
		buildPlan(primary, []*metadatav1.RequestSpec{extra}),
		buildPlan(primary, nil, nil),
		buildPlan(primary, nil, map[string]string{}),
	} {
		if got != nil {
			t.Fatalf("plan = %v, want nil (unresolved server ref keeps the relay skip)", got)
		}
	}

	// A client: ref stays unsupported even with the secrets map present.
	clientSpec := &metadatav1.RequestSpec{
		Method: "GET", UrlTemplate: "https://upstream/x?token={token}",
		Variables: map[string]*metadatav1.VariableValue{"token": redactedRefVar("client:token")},
	}
	if plan := buildPlan(clientSpec, nil, map[string]string{"token": "t"}); plan != nil {
		t.Fatalf("plan = %v, want nil (client: refs are never relayed)", plan)
	}
}
